const FEST = {"2026-01-01": "Año Nuevo", "2026-01-06": "Epifanía del Señor", "2026-04-03": "Viernes Santo", "2026-05-01": "Fiesta del Trabajo", "2026-05-15": "San Isidro de Villaverde", "2026-08-15": "Asunción de la Virgen", "2026-10-12": "Fiesta Nacional de España", "2026-10-30": "Fiesta de la Vendimia de Villaverde", "2026-11-01": "Todos los Santos", "2026-12-06": "Día de la Constitución", "2026-12-08": "Inmaculada Concepción", "2026-12-25": "Natividad del Señor", "2027-01-01": "Año Nuevo", "2027-01-06": "Epifanía del Señor", "2027-03-26": "Viernes Santo", "2027-05-01": "Fiesta del Trabajo", "2027-05-17": "San Isidro de Villaverde (trasladado al lunes)", "2027-08-15": "Asunción de la Virgen", "2027-10-12": "Fiesta Nacional de España", "2027-10-29": "Fiesta de la Vendimia de Villaverde", "2027-11-01": "Todos los Santos", "2027-12-06": "Día de la Constitución", "2027-12-08": "Inmaculada Concepción", "2027-12-25": "Natividad del Señor"};
const iso = d => d.toISOString().slice(0,10);
const parse = s => { const d = new Date(String(s).slice(0,10) + 'T00:00:00Z'); if (isNaN(d)) throw new Error('Fecha no válida: ' + s + ' (usa AAAA-MM-DD)'); if (d.getUTCFullYear() < 2026 || d.getUTCFullYear() > 2027) throw new Error('El calendario solo cubre 2026 y 2027'); return d; };
const habil = d => { const w = d.getUTCDay(); return w !== 0 && w !== 6 && !FEST[iso(d)]; };
const DIAS = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const larga = d => DIAS[d.getUTCDay()] + ' ' + iso(d);
try {
 const ini = parse(query.fecha_inicio); const n = Number(query.cantidad); const tipo = query.tipo;
 if (!Number.isInteger(n) || n < 1) return 'Error: cantidad debe ser un entero positivo';
 let d = new Date(ini); const saltados = [];
 if (tipo === 'habiles') { let k = n; while (k > 0) { d.setUTCDate(d.getUTCDate()+1); if (habil(d)) k--; else if (FEST[iso(d)]) saltados.push(iso(d) + ' ' + FEST[iso(d)]); } }
 else if (tipo === 'naturales') { d.setUTCDate(d.getUTCDate()+n); }
 else if (tipo === 'meses') { const y = ini.getUTCFullYear(), m = ini.getUTCMonth()+n, day = ini.getUTCDate(); const last = new Date(Date.UTC(y, m+1, 0)).getUTCDate(); d = new Date(Date.UTC(y, m, Math.min(day,last))); }
 else return "Error: tipo debe ser 'habiles', 'naturales' o 'meses'";
 let fin = new Date(d); let movido = false; while (!habil(fin)) { fin.setUTCDate(fin.getUTCDate()+1); movido = true; }
 return JSON.stringify({ fecha_inicio: iso(ini), cantidad: n, tipo, fecha_fin: larga(fin), pasado_a_habil: movido, festivos_saltados: saltados });
} catch (e) { return 'Error: ' + e.message; }

